package java.util;
public final class Arrays { private Arrays(){} public static int hashCode(Object[] a){if(a==null)return 0;int h=1;for(Object x:a)h=31*h+Objects.hashCode(x);return h;} public static <T> void sort(T[] a,Comparator<? super T> c){Object[] tmp=new Object[a.length];merge(a,tmp,0,a.length,c);} private static <T> void merge(T[] a,Object[] tmp,int lo,int hi,Comparator<? super T> c){if(hi-lo<2)return;int m=(lo+hi)>>>1;merge(a,tmp,lo,m,c);merge(a,tmp,m,hi,c);int i=lo,j=m,k=lo;while(i<m||j<hi){if(j==hi||(i<m&&(c==null?((Comparable)a[i]).compareTo(a[j]):c.compare(a[i],a[j]))<=0))tmp[k++]=a[i++];else tmp[k++]=a[j++];}for(i=lo;i<hi;i++)a[i]=(T)tmp[i];} }
